Input: {"question": "Which award did Miguel Woites receive?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "d1", "start": 0, "end": 74, "text": "**Argentine Journalist Miguel Woites Honored with Prestigious Order of St."}, "D1S2": {"document_number": 1, "doc_id": "d1", "start": 75, "end": 94, "text": "Gregory the Great**"}, "D1S3": {"document_number": 1, "doc_id": "d1", "start": 96, "end": 219, "text": "In a ceremony held at the Vatican City, renowned Argentine journalist Miguel Woites was conferred the esteemed Order of St."}, "D1S4": {"document_number": 1, "doc_id": "d1", "start": 220, "end": 280, "text": "Gregory the Great, a highest honor bestowed by the Holy See."}, "D1S5": {"document_number": 1, "doc_id": "d1", "start": 281, "end": 424, "text": "This prestigious award recognizes Woites' outstanding contributions to the field of journalism and his commitment to promoting Catholic values."}, "D1S6": {"document_number": 1, "doc_id": "d1", "start": 425, "end": 441, "text": "The Order of St."}, "D1S7": {"document_number": 1, "doc_id": "d1", "start": 442, "end": 535, "text": "Gregory the Great is an honorary order of knighthood established in 1831 by Pope Gregory XVI."}, "D1S8": {"document_number": 1, "doc_id": "d1", "start": 536, "end": 642, "text": "It is awarded to individuals who have demonstrated exceptional service to the Catholic Church and society."}, "D1S9": {"document_number": 1, "doc_id": "d1", "start": 643, "end": 807, "text": "Woites, a respected figure in Argentine journalism, has been recognized for his tireless efforts in promoting social justice, human rights, and interfaith dialogue."}, "D1S10": {"document_number": 1, "doc_id": "d1", "start": 808, "end": 916, "text": "\"I am deeply humbled and grateful to receive this prestigious award,\" Woites said in an exclusive interview."}, "D1S11": {"document_number": 1, "doc_id": "d1", "start": 917, "end": 1006, "text": "\"It is an honor not only for me but also for the entire Argentine journalistic community."}, "D1S12": {"document_number": 1, "doc_id": "d1", "start": 1007, "end": 1092, "text": "I dedicate this recognition to all those who have supported me throughout my career.\""}, "D1S13": {"document_number": 1, "doc_id": "d1", "start": 1093, "end": 1187, "text": "Woites' work has been widely acclaimed for its objectivity, fairness, and commitment to truth."}, "D1S14": {"document_number": 1, "doc_id": "d1", "start": 1188, "end": 1318, "text": "His investigative reporting has shed light on various social and political issues, inspiring positive change in Argentine society."}, "D1S15": {"document_number": 1, "doc_id": "d1", "start": 1319, "end": 1453, "text": "\"Miguel Woites is a shining example of journalistic excellence,\" said Archbishop Mario Poli, a prominent Catholic leader in Argentina."}, "D1S16": {"document_number": 1, "doc_id": "d1", "start": 1454, "end": 1537, "text": "\"His dedication to promoting Catholic values and social justice is truly inspiring."}, "D1S17": {"document_number": 1, "doc_id": "d1", "start": 1538, "end": 1614, "text": "This award is a well-deserved recognition of his outstanding contributions.\""}, "D1S18": {"document_number": 1, "doc_id": "d1", "start": 1615, "end": 1728, "text": "According to the Vatican's official records, Woites is the first Argentine journalist to receive the Order of St."}, "D1S19": {"document_number": 1, "doc_id": "d1", "start": 1729, "end": 1747, "text": "Gregory the Great."}, "D1S20": {"document_number": 1, "doc_id": "d1", "start": 1748, "end": 1837, "text": "This distinction is a testament to his remarkable career, which spans over three decades."}, "D1S21": {"document_number": 1, "doc_id": "d1", "start": 1838, "end": 2011, "text": "Data from the Argentine Journalists' Association reveals that Woites has received numerous awards for his work, including the prestigious Konex Award for Journalism in 2017."}, "D1S22": {"document_number": 1, "doc_id": "d1", "start": 2012, "end": 2128, "text": "His investigative reporting has led to significant reforms in areas such as education, healthcare, and human rights."}, "D1S23": {"document_number": 1, "doc_id": "d1", "start": 2129, "end": 2145, "text": "The Order of St."}, "D1S24": {"document_number": 1, "doc_id": "d1", "start": 2146, "end": 2271, "text": "Gregory the Great is conferred upon individuals who have demonstrated exceptional service to the Catholic Church and society."}, "D1S25": {"document_number": 1, "doc_id": "d1", "start": 2272, "end": 2411, "text": "Previous recipients of this award include notable figures such as Mother Teresa, Saint John Paul II, and former US President Ronald Reagan."}, "D1S26": {"document_number": 1, "doc_id": "d1", "start": 2412, "end": 2580, "text": "Woites' recognition serves as a beacon of inspiration for journalists and individuals around the world who are committed to promoting truth, justice, and human dignity."}, "D2S1": {"document_number": 2, "doc_id": "d2", "start": 0, "end": 94, "text": "**Renowned Argentine Journalist Miguel Woites Honored with Prestigious Guggenheim Fellowship**"}, "D2S2": {"document_number": 2, "doc_id": "d2", "start": 96, "end": 307, "text": "Buenos Aires, Argentina - In a move that has sent shockwaves through the literary and journalistic communities, Miguel Woites, a veteran Argentine journalist, has been awarded the esteemed Guggenheim Fellowship."}, "D2S3": {"document_number": 2, "doc_id": "d2", "start": 308, "end": 531, "text": "The prestigious grant, awarded annually to exceptional artists and scholars, recognizes Woites' outstanding contributions to the field of journalism and his unwavering commitment to telling the stories that need to be told."}, "D2S4": {"document_number": 2, "doc_id": "d2", "start": 532, "end": 686, "text": "Woites, known for his fearless reporting and in-depth investigations, has spent decades covering some of the most pressing issues in Argentina and beyond."}, "D2S5": {"document_number": 2, "doc_id": "d2", "start": 687, "end": 865, "text": "His work has taken him from the streets of Buenos Aires to the depths of the Amazon rainforest, and his writing has been hailed for its lyricism, nuance, and unflinching honesty."}, "D2S6": {"document_number": 2, "doc_id": "d2", "start": 866, "end": 987, "text": "\"I am humbled and grateful to receive this incredible honor,\" Woites said in an exclusive interview with our publication."}, "D2S7": {"document_number": 2, "doc_id": "d2", "start": 988, "end": 1133, "text": "\"The Guggenheim Fellowship is a testament to the power of storytelling and the importance of a free press in holding those in power accountable.\""}, "D2S8": {"document_number": 2, "doc_id": "d2", "start": 1134, "end": 1202, "text": "Woites' work has been widely praised by his peers and critics alike."}, "D2S9": {"document_number": 2, "doc_id": "d2", "start": 1203, "end": 1319, "text": "\"Miguel is a true giant in the world of journalism,\" said Maria Rodriguez, a fellow journalist and friend of Woites."}, "D2S10": {"document_number": 2, "doc_id": "d2", "start": 1320, "end": 1440, "text": "\"His dedication to his craft is inspiring, and his writing has a way of transporting readers to the heart of the story.\""}, "D2S11": {"document_number": 2, "doc_id": "d2", "start": 1441, "end": 1553, "text": "The Guggenheim Fellowship, established in 1925, is one of the most respected and competitive awards in the arts."}, "D2S12": {"document_number": 2, "doc_id": "d2", "start": 1554, "end": 1657, "text": "This year's recipients include a diverse range of artists, writers, and scholars from around the world."}, "D2S13": {"document_number": 2, "doc_id": "d2", "start": 1658, "end": 1737, "text": "Woites is the first Argentine journalist to receive the award in over a decade."}, "D2S14": {"document_number": 2, "doc_id": "d2", "start": 1738, "end": 1889, "text": "According to the John Simon Guggenheim Memorial Foundation, which administers the fellowship, Woites was selected from a pool of over 3,000 applicants."}, "D2S15": {"document_number": 2, "doc_id": "d2", "start": 1890, "end": 2027, "text": "The foundation cited his \"exceptional talent, dedication, and contributions to the field of journalism\" as the reasons for his selection."}, "D2S16": {"document_number": 2, "doc_id": "d2", "start": 2028, "end": 2182, "text": "Woites plans to use the fellowship to pursue a new project, exploring the intersection of environmental degradation and human rights in the Amazon region."}, "D2S17": {"document_number": 2, "doc_id": "d2", "start": 2183, "end": 2343, "text": "\"This award gives me the opportunity to delve deeper into the stories that need to be told, and to amplify the voices of those who are often silenced,\" he said."}, "D2S18": {"document_number": 2, "doc_id": "d2", "start": 2344, "end": 2414, "text": "As news of the award spread, tributes poured in from across the globe."}}, "original_cards": [{"doc_id": "d1", "card_id": "d1:c1", "entity": "Miguel Woites", "scope": "Award received", "claim": "Data from the Argentine Journalists' Association reveals that Woites has received numerous awards for his work, including the prestigious Konex Award for Journalism in 2017.", "answer": "Konex Award for Journalism", "quote": "Data from the Argentine Journalists' Association reveals that Woites has received numerous awards for his work, including the prestigious Konex Award for Journalism in 2017.", "original_document_number": 1}], "current_answers": ["Order of St. Gregory the Great", "Guggenheim Fellowship", "Konex Award for Journalism"], "candidate_answers": [{"candidate_id": "R0", "answer": "Order of St. Gregory the Great", "origin": "initial"}, {"candidate_id": "R1", "answer": "Guggenheim Fellowship", "origin": "initial"}, {"candidate_id": "R2", "answer": "Konex Award for Journalism", "origin": "initial"}]}

